// PLANTILLA de historico: sustituye este marcador por tu escena 3D.
// Gestos: tiltLeft, puff. Sonido: window.folio.sfx.play("historico")
var k = 0;
function init() { this.scale.setScalar(1); }
function tiltLeft() { k = 1; window.folio?.sfx.play("historico"); }
function puff() { k = 1; window.folio?.sfx.play("pop"); }
function update(event) { k = Math.max(0, k - event.delta / 700); this.scale.setScalar(1 + k * 1.5); this.rotation.y += event.delta / 800; }
